use crate::model::{Summary,Event};

pub fn run(events: &[Event], initial: i64) -> Summary {
    let mut balance = initial;
    let mut rejected = 0;
    let mut peak = initial;
    let mut audit = Vec::with_capacity(events.len());
    let mut locked = false;

    for event in events {
        match event {
            Event::Credit(amount) => {
                if (0..=1_000_000).contains(amount) {
                    balance += amount;
                    peak = peak.max(balance);
                } else {
                    rejected += 1;
                }
            }
            Event::Debit(amount) => {
                if !(0..=1_000_000).contains(amount)
                    || locked
                    || *amount > balance
                {
                    rejected += 1;
                } else {
                    balance -= amount;
                }
            }
            Event::Lock => locked = true,
            Event::Unlock => locked = false,
        }
        audit.push(balance);
    }

    Summary { balance, rejected, peak, audit }
}

